import XCTest

final class ReplyTestUITests: XCTestCase {
    func testDumpMenu() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        let bookClub = app.staticTexts["Book Club"].firstMatch
        XCTAssertTrue(bookClub.waitForExistence(timeout: 30), "Book Club not found")
        bookClub.tap()

        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 10) {
            gotIt.tap()
        }

        let msg = app.textViews["Loving it so far, the worldbuilding is great."].firstMatch
        XCTAssertTrue(msg.waitForExistence(timeout: 20), "message not found")
        msg.press(forDuration: 1.2)
        Thread.sleep(forTimeInterval: 3)

        try app.debugDescription.write(toFile: "/tmp/element_menu_hierarchy.txt", atomically: true, encoding: .utf8)
    }
}
